	@Test
	void statementAndQuotedTermValuesRemainUsableAfterTheirViewCloses(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc").setForceSync(true));
		IRI subject = VF.createIRI("urn:snapshot-lifetime:subject");
		IRI context = VF.createIRI("urn:snapshot-lifetime:context");
		Literal innerValue = VF.createLiteral("inner quoted value");
		TripleTerm inner = VF.createTripleTerm(subject, PREDICATE, innerValue);
		TripleTerm outer = VF.createTripleTerm(subject, PREDICATE, inner);
		Statement detachedStatement;
		TripleTerm detachedTerm;

		store.init();
		try {
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(subject, PREDICATE, outer, context);
				writer.commit();
			}

			try (SailDataset dataset = store.getBackingStore()
					.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ)) {
				try (CloseableIteration<? extends Statement> statements = dataset.getStatements(subject, PREDICATE,
						outer, context)) {
					assertTrue(statements.hasNext());
					detachedStatement = statements.next();
					assertFalse(statements.hasNext());
				}
				try (CloseableIteration<? extends TripleTerm> triples = dataset.getTriples(subject, PREDICATE, inner)) {
					assertTrue(triples.hasNext());
					detachedTerm = triples.next();
					assertFalse(triples.hasNext());
				}
			}

			assertEquals(subject.stringValue(), detachedStatement.getSubject().stringValue());
			TripleTerm detachedOuter = (TripleTerm) detachedStatement.getObject();
			assertEquals(subject.stringValue(), detachedOuter.getSubject().stringValue());
			TripleTerm detachedInner = (TripleTerm) detachedOuter.getObject();
			assertEquals("inner quoted value", ((Literal) detachedInner.getObject()).getLabel());
			assertEquals(context.stringValue(), detachedStatement.getContext().stringValue());
			assertEquals(subject.stringValue(), detachedTerm.getSubject().stringValue());
			TripleTerm detachedNested = (TripleTerm) detachedTerm.getObject();
			assertEquals("inner quoted value", ((Literal) detachedNested.getObject()).getLabel());
		} finally {
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void escapedNestedValuesRemainUsableAfterRepositoryShutdown(@TempDir File dataDir) throws Exception {
		IRI subject = VF.createIRI("urn:shutdown-values:subject");
		IRI context = VF.createIRI("urn:shutdown-values:context");
		IRI datatype = VF.createIRI("urn:shutdown-values:datatype");
		Literal literal = VF.createLiteral("deferred until shutdown", datatype);
		TripleTerm inner = VF.createTripleTerm(subject, PREDICATE, literal);
		TripleTerm outer = VF.createTripleTerm(subject, PREDICATE, inner);
		SailRepository repository = new SailRepository(new LmdbStore(dataDir));
		Statement escaped;
		repository.init();
		try {
			try (RepositoryConnection writer = repository.getConnection()) {
				writer.add(subject, PREDICATE, outer, context);
			}
			try (RepositoryConnection reader = repository.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				try (CloseableIteration<? extends Statement> statements = reader.getStatements(null, null, null,
						false)) {
					assertTrue(statements.hasNext());
					escaped = statements.next();
				}
				reader.commit();
			}
		} finally {
			repository.shutDown();
		}
		assertEquals(subject.stringValue(), escaped.getSubject().stringValue());
		assertEquals(context, escaped.getContext());
		TripleTerm escapedOuter = (TripleTerm) escaped.getObject();
		TripleTerm escapedInner = (TripleTerm) escapedOuter.getObject();
		Literal escapedLiteral = (Literal) escapedInner.getObject();
		assertEquals(literal.getLabel(), escapedLiteral.getLabel());
		assertEquals(datatype, escapedLiteral.getDatatype());
		assertEquals(outer.hashCode(), escapedOuter.hashCode());
		assertEquals(outer, escapedOuter);
	}

