	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void ambientCleanupReaderCanReturnBeforeMeasuredSnapshotFailure(@TempDir File dataDir) throws Exception {
		FailingReadSnapshotStore store = new FailingReadSnapshotStore(dataDir, true);
		CountDownLatch ambientReader = new CountDownLatch(1);
		CountDownLatch releaseReader = new CountDownLatch(1);
		AtomicBoolean holdNextReader = new AtomicBoolean(true);
		try {
			store.init();
			LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			store.valueStore.getTxnManager().setAdmissionObserverForTest(txn -> {
				if (Thread.currentThread().getName().equals("LmdbValueCleanup")
						&& holdNextReader.compareAndSet(true, false)) {
					ambientReader.countDown();
					try {
						assertTrue(releaseReader.await(20, TimeUnit.SECONDS));
					} catch (InterruptedException interrupted) {
						Thread.currentThread().interrupt();
						throw new AssertionError(interrupted);
					}
				}
			});
			store.getBackingStore().asyncValueCleanupCoordinator().signal();
			assertTrue(ambientReader.await(10, TimeUnit.SECONDS));
			int permitsWithAmbientReader = availableSnapshotReaderPermits(store.valueStore.getTxnManager());
			releaseReader.countDown();
			// Join the real idle worker before measuring conservation of only the injected paired acquisition.
			store.getBackingStore().stopAsyncValueCleanupForShutdown();
			assertEquals(permitsWithAmbientReader + 1,
					availableSnapshotReaderPermits(store.valueStore.getTxnManager()),
					"an unrelated cleanup reader legitimately returns one ordinary permit before acquisition");
			assertFailedValueSnapshotReturnsReservations(store);
		} finally {
			releaseReader.countDown();
			store.expectedSnapshotThread = null;
			store.shutDown();
		}
	}

	private static int availableSnapshotReaderPermits(TxnManager manager) {
		return manager.availableReadTxnSlots(Integer.MAX_VALUE, 0);
	}

	private static void assertFailedValueSnapshotReturnsReservations(FailingReadSnapshotStore store) throws Exception {
		LmdbGcTestMaintenance.awaitPostReady(store);
		assertTrue(store.awaitIndexRebuild(10, TimeUnit.SECONDS),
				"native index maintenance must finish before admission");
		LmdbSailStore backingStore = store.getBackingStore();
		TripleStore tripleStore = store.tripleStore;
		ValueStore valueStore = store.valueStore;
		assertSame(tripleStore, backingStore.getTripleStore(), "the fixture must observe the admitted TripleStore");
		assertSame(valueStore, backingStore.valueStore(), "the fixture must inject into the admitted ValueStore");
		assertNull(backingStore.currentReadViewLease(), "the measured acquisition must start a fresh paired view");
		int triplePermits = availableSnapshotReaderPermits(tripleStore.getTxnManager());
		int valuePermits = availableSnapshotReaderPermits(valueStore.getTxnManager());
		store.expectedTriplePermits = triplePermits;
		store.expectedSnapshotThread = Thread.currentThread();
		store.failNextSnapshotStart.set(true);
		int startsBefore = store.snapshotStartCalls.get();
		SailException failure = assertThrows(SailException.class,
				() -> {
					try (SailDataset ignored = backingStore.getExplicitSailSource()
							.dataset(IsolationLevels.SNAPSHOT_READ)) {
					}
				},
				() -> "paired starts before/after=" + startsBefore + "/" + store.snapshotStartCalls.get()
						+ ", measured starts=" + store.measuredSnapshotStartCalls.get()
						+ ", fault pending=" + store.failNextSnapshotStart.get()
						+ ", bound view=" + backingStore.currentReadViewLease());
		assertFalse(store.failNextSnapshotStart.get(), "the measured paired acquisition must consume the fault");
		assertEquals(1, store.measuredSnapshotStartCalls.get(),
				"exactly the measured caller must enter the injected second-environment start");
		assertFalse(failure instanceof SailConflictException,
				"an injected native snapshot-start I/O failure is not a transaction conflict");
		assertTrue(failure.getCause() instanceof IOException,
				"the injected second-environment start failure must remain the reported cause");
		assertEquals("injected ValueStore snapshot start failure", failure.getCause().getMessage());
		assertEquals(triplePermits, availableSnapshotReaderPermits(tripleStore.getTxnManager()),
				"failed paired acquisition must return the first environment's reader permit");
		assertEquals(valuePermits, availableSnapshotReaderPermits(valueStore.getTxnManager()),
				"failed ValueStore acquisition must return its reserved reader permit");
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void unobservedSnapshotQueryRestartsAfterTripleStoreMapGrowth(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(TRIPLE_STORE_GROWTH_MAP_SIZE)
				.setMapGrowthThreshold(TRIPLE_STORE_GROWTH_THRESHOLD)
				.setMapGrowthReadDrainTimeoutMillis(2_000)
				.setAutoGrow(true));
		SailRepository repository = new SailRepository(store);
		IRI predicate = VF.createIRI("urn:snapshot-lifetime:unobserved:predicate");
		IRI subject = VF.createIRI("urn:snapshot-lifetime:unobserved:published");
		long initialMapSize;

		repository.init();
		try {
			TripleStore tripleStore = tripleStoreOf(store);
			initialMapSize = mapSize(tripleStore);
			try (RepositoryConnection reader = repository.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				TupleQueryResult results = reader.prepareTupleQuery("SELECT ?value WHERE { <" + subject.stringValue()
						+ "> <" + predicate.stringValue() + "> ?value }").evaluate();
				LmdbStoreConnection readerSailConnection = (LmdbStoreConnection) ((SailRepositoryConnection) reader)
						.getSailConnection();
				List<Object> readViewsBeforeGrowth = snapshotReadViewLeases(readerSailConnection);
				assertFalse(readViewsBeforeGrowth.isEmpty(), "the query must retain its paired native read view");
				try (results; RepositoryConnection writer = repository.getConnection()) {
					writer.begin(IsolationLevels.SNAPSHOT);
					String namespace = addTripleStoreGrowthDemand(
							((SailRepositoryConnection) writer).getSailConnection(), initialMapSize);
					for (int i = 0; i < 10_000; i++) {
						writer.add(VF.createIRI("urn:snapshot-lifetime:unobserved:" + i), predicate,
								VF.createLiteral("value"));
					}
					writer.add(subject, predicate, VF.createLiteral("published"));
					writer.commit();
					awaitTripleStoreGrowth(store, tripleStore, initialMapSize, namespace);
					for (Object readView : readViewsBeforeGrowth) {
						assertTrue((boolean) privateField(readView, "closed"),
								"eligible replay must retire the old native read view before map growth");
						assertNull(privateField(readView, "invalidatedKind"),
								"successful replay must not depend on forced map-growth invalidation");
					}
					assertTrue(mapSize(tripleStore) > initialMapSize,
							"the writer must grow TripleStore while the query result is still unobserved");

					assertTrue(results.hasNext(),
							"a query with no outward observation must restart on the complete post-growth snapshot");
					assertEquals("published", results.next().getValue("value").stringValue());
					assertFalse(results.hasNext());
				}
				reader.commit();
			}
		} finally {
			repository.shutDown();
		}
	}

	private List<Object> snapshotReadViewLeases(LmdbStoreConnection connection) throws Exception {
		Set<Object> readViews = Collections.newSetFromMap(new IdentityHashMap<>());
		addHistoricalReadViews(readViews, privateField(connection, "readAttemptLease"));
		Set<?> operationAttempts = (Set<?>) privateField(connection, "operationReadAttempts");
		for (Object operationAttempt : operationAttempts) {
			addHistoricalReadViews(readViews, privateField(operationAttempt, "lease"));
		}
		return new ArrayList<>(readViews);
	}

	private void addHistoricalReadViews(Set<Object> readViews, Object attempt) throws Exception {
		if (attempt != null) {
			Map<?, ?> historicalViews = (Map<?, ?>) privateField(attempt, "historicalViews");
			readViews.addAll(historicalViews.keySet());
		}
	}

	private static String addTripleStoreGrowthDemand(SailConnection writer, long initialMapSize) throws SailException {
		int namespaceDemand = Math.toIntExact((long) Math.ceil(initialMapSize * TRIPLE_STORE_GROWTH_THRESHOLD));
		String namespace = "urn:snapshot-lifetime:growth-demand:" + "n".repeat(namespaceDemand);
		writer.setNamespace("growth-demand", namespace);
		return namespace;
	}

	private static String addTripleStoreGrowthDemand(SailSink writer, long initialMapSize) throws SailException {
		int namespaceDemand = Math.toIntExact((long) Math.ceil(initialMapSize * TRIPLE_STORE_GROWTH_THRESHOLD));
		String namespace = "urn:snapshot-lifetime:growth-demand:" + "n".repeat(namespaceDemand);
		writer.setNamespace("growth-demand", namespace);
		return namespace;
	}

	private static String addTripleStoreHardGrowthDemand(SailConnection writer, TripleStore tripleStore)
			throws Exception {
		long mapSize = tripleStore.mapSizeBytes();
		int namespaceDemand = Math.toIntExact(mapSize);
		assertTrue(new MapGrowthPolicy(TRIPLE_STORE_GROWTH_THRESHOLD).hardCapacityRequired(mapSize,
				tripleStore.occupiedBytes(), namespaceDemand),
				"the namespace must require hard capacity before its native publication can finish");
		String namespace = "urn:snapshot-lifetime:hard-growth-demand:" + "n".repeat(namespaceDemand);
		writer.setNamespace("growth-demand", namespace);
		return namespace;
	}

	private void awaitTripleStoreGrowth(LmdbStore store, TripleStore tripleStore, long initialMapSize,
			String namespace) throws Exception {
		try (SailConnection barrier = store.getConnection()) {
			barrier.begin(IsolationLevels.SNAPSHOT);
			assertEquals(namespace, barrier.getNamespace("growth-demand"),
					"an independent admission barrier must observe the authoritative namespace publication");
			barrier.rollback();
		}
		assertTrue(mapSize(tripleStore) > initialMapSize,
				"the independent begin/rollback must finish the pending TripleStore growth");
	}

	private void awaitGrowthPhase(LmdbStore store, LmdbSailStore.GrowthPhase expected) {
		awaitGrowthPhase(store, expected, TimeUnit.SECONDS.toMillis(15));
	}

	private void awaitGrowthPhase(LmdbStore store, LmdbSailStore.GrowthPhase expected, long timeoutMillis) {
		long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(timeoutMillis);
		while (store.getBackingStore().growthMetricsSnapshot().currentPhase() != expected) {
			if (System.nanoTime() >= deadline) {
				throw new AssertionError("expected map growth phase " + expected + ", but observed "
						+ store.getBackingStore().growthMetricsSnapshot().currentPhase());
			}
			Thread.yield();
		}
	}

	private Object privateField(Object instance, String name) throws ReflectiveOperationException {
		Field field = instance.getClass().getDeclaredField(name);
		field.setAccessible(true);
		return field.get(instance);
	}

	private boolean isObserved(Object result, boolean expected) {
		try {
			return (boolean) privateField(result, "observed") == expected;
		} catch (ReflectiveOperationException e) {
			throw new AssertionError(e);
		}
	}

	private Set<Object> snapshotGrowthViews(Object result) throws ReflectiveOperationException {
		Set<?> growthViews = (Set<?>) privateField(result, "growthViews");
		Set<Object> snapshot = Collections.newSetFromMap(new IdentityHashMap<>());
		snapshot.addAll(growthViews);
		return snapshot;
	}

	private Set<Object> snapshotIterationReadViews(SailConnection connection, Object result) throws Exception {
		Object lock = privateField(connection, "readAttemptLock");
		synchronized (lock) {
			List<?> readViews = (List<?>) privateField(result, "readViews");
			Set<Object> snapshot = Collections.newSetFromMap(new IdentityHashMap<>());
			snapshot.addAll(readViews);
			return snapshot;
		}
	}

	private <T extends Throwable> T findCause(Throwable failure, Class<T> causeType) {
		for (Throwable cause = failure; cause != null; cause = cause.getCause()) {
			if (causeType.isInstance(cause)) {
				return causeType.cast(cause);
			}
		}
		return null;
	}

	private void awaitForcedReadViewInvalidation(LmdbStore store, Future<?> writer, MapGrowthMetrics.Snapshot before)
			throws Exception {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(15);
		while (System.nanoTime() - deadline < 0) {
			MapGrowthMetrics.Snapshot current = store.getBackingStore().growthMetricsSnapshot();
			// Entering quiescence starts reader grace; only forced invalidation establishes cancellation.
			if (current.forcedInvalidatedViews() > before.forcedInvalidatedViews()) {
				return;
			}
			if (writer.isDone()) {
				writer.get();
				current = store.getBackingStore().growthMetricsSnapshot();
				if (current.forcedInvalidatedViews() > before.forcedInvalidatedViews()) {
					return;
				}
				throw new AssertionError("the buffered writer completed without invalidating its pinned read views; "
						+ "metrics=" + current);
			}
			LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(5));
		}
		MapGrowthMetrics.Snapshot current = store.getBackingStore().growthMetricsSnapshot();
		throw new AssertionError("writer did not invalidate its pinned read views after reader grace; phase="
				+ current.currentPhase() + ", forcedInvalidatedViews=" + current.forcedInvalidatedViews() + ", before="
				+ before.forcedInvalidatedViews());
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void unobservedNonEmptySnapshotQueryRestartsAfterTripleStoreMapGrowth(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(TRIPLE_STORE_GROWTH_MAP_SIZE)
				.setMapGrowthThreshold(TRIPLE_STORE_GROWTH_THRESHOLD)
				.setMapGrowthReadDrainTimeoutMillis(150)
				.setAutoGrow(true));
		SailRepository repository = new SailRepository(store);
		IRI predicate = VF.createIRI("urn:snapshot-lifetime:lazy:predicate");
		IRI growthPredicate = VF.createIRI("urn:snapshot-lifetime:lazy:growth-predicate");
		IRI subjectBefore = VF.createIRI("urn:snapshot-lifetime:lazy:before");
		IRI subjectAfter = VF.createIRI("urn:snapshot-lifetime:lazy:after");
		long initialMapSize;

		repository.init();
		try {
			TripleStore tripleStore = tripleStoreOf(store);
			try (RepositoryConnection seed = repository.getConnection()) {
				seed.begin(IsolationLevels.SNAPSHOT);
				seed.add(subjectBefore, predicate, VF.createLiteral("before"));
				seed.commit();
			}
			initialMapSize = mapSize(tripleStore);
			try (RepositoryConnection reader = repository.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				TupleQueryResult results = reader
						.prepareTupleQuery("SELECT ?value WHERE { ?s <" + predicate.stringValue()
								+ "> ?value }")
						.evaluate();
				try (results; RepositoryConnection writer = repository.getConnection()) {
					writer.begin(IsolationLevels.SNAPSHOT);
					String namespace = addTripleStoreGrowthDemand(
							((SailRepositoryConnection) writer).getSailConnection(), initialMapSize);
					for (int i = 0; i < 10_000; i++) {
						writer.add(VF.createIRI("urn:snapshot-lifetime:lazy:" + i), growthPredicate,
								VF.createLiteral("growth"));
					}
					writer.add(subjectAfter, predicate, VF.createLiteral("published"));
					writer.commit();
					awaitTripleStoreGrowth(store, tripleStore, initialMapSize, namespace);
					assertTrue(mapSize(tripleStore) > initialMapSize,
							"the lazy nonempty query must span actual TripleStore map growth");

					Set<String> values = new HashSet<>();
					while (results.hasNext()) {
						values.add(results.next().getValue("value").stringValue());
					}
					assertEquals(Set.of("before", "published"), values,
							"the whole unobserved query must replay over one complete post-growth snapshot");
				}
				reader.commit();
			}
		} finally {
			repository.shutDown();
		}
	}

	private Set<Object> awaitResultGrowthViews(SailConnection connection, Object result) throws Exception {
		Object lock = privateField(connection, "readAttemptLock");
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(15);
		synchronized (lock) {
			while (privateField(result, "growthToken") == null) {
				long remaining = deadline - System.nanoTime();
				if (remaining <= 0) {
					throw new AssertionError("the unobserved iteration must receive the map-growth token");
				}
				TimeUnit.NANOSECONDS.timedWait(lock, remaining);
			}
			Set<Object> growthViews = snapshotGrowthViews(result);
			if (growthViews.isEmpty()) {
				throw new AssertionError("the unobserved iteration must record its pre-growth native views");
			}
			return growthViews;
		}
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void nonNullUpdateContextPreventsReplayBeforeFirstMutation(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(4L * 1024 * 1024)
				.setValueDBSize(TRIPLE_STORE_GROWTH_MAP_SIZE)
				.setBulkOperationSize(0)
				.setMapGrowthThreshold(TRIPLE_STORE_GROWTH_THRESHOLD)
				.setMapGrowthReadDrainTimeoutMillis(0)
				.setAutoGrow(true));
		IRI predicate = VF.createIRI("urn:snapshot-lifetime:update-attempt:predicate");
		IRI subject = VF.createIRI("urn:snapshot-lifetime:update-attempt:published");
		long initialMapSize;

		store.init();
		try {
			LmdbGcTestMaintenance.awaitPostReady(store);
			assertTrue(store.awaitIndexRebuild(10, TimeUnit.SECONDS),
					"native index maintenance must finish before growth");
			TripleStore tripleStore = tripleStoreOf(store);
			initialMapSize = mapSize(tripleStore);
			ValueStore values = valueStoreOf(store);
			long initialValueMapSize = mapSize(values);
			String namespace = "urn:snapshot-lifetime:update-attempt:growth:";
			List<Statement> growthBatch = new ArrayList<>(10_001);
			for (int i = 0; i < 10_000; i++) {
				growthBatch.add(VF.createStatement(VF.createIRI("urn:u:" + i), predicate, VF.createLiteral("value")));
			}
			growthBatch.add(VF.createStatement(subject, predicate, VF.createLiteral("published")));
			SailSource.WritePreflight estimate = new SailSource.WritePreflight(growthBatch,
					List.of(new SailSource.NamespaceUpdate("growth-demand", namespace)), Set.of(), Set.of(), false,
					false);
			long tripleEstimate = tripleStore.estimateWriteBytes(estimate);
			long valueEstimate = values.estimateWriteBytes(estimate);
			assertTrue(tripleStore.requiresResizeForEstimatedWrite(tripleEstimate),
					() -> "the incremental batch must project TripleStore pressure: bytes=" + tripleEstimate
							+ ", map=" + initialMapSize);
			assertFalse(values.requiresResizeForEstimatedWrite(valueEstimate),
					() -> "the incremental batch must fit ValueStore admission: bytes=" + valueEstimate
							+ ", map=" + initialValueMapSize);
			MapGrowthMetrics.Snapshot before = store.getBackingStore().growthMetricsSnapshot();
			try (ExecutorService writers = Executors.newSingleThreadExecutor();
					SailConnection reader = store.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				reader.startUpdate(new UpdateContext(new InsertData("INSERT DATA {}"), null, null, false));
				Future<String> writer = null;
				CountDownLatch writesBuffered = new CountDownLatch(1);
				try (CloseableIteration<? extends Statement> results = reader.getStatements(subject, predicate, null,
						false)) {
					Object originalReadView = privateField(reader, "transactionReadView");
					assertNotNull(originalReadView,
							"the update owner's read snapshot must be established before growth");
					writer = writers.submit(() -> {
						try (SailConnection growthWriter = store.getConnection()) {
							growthWriter.begin(IsolationLevels.SNAPSHOT);
							growthWriter.setNamespace("growth-demand", namespace);
							for (Statement statement : growthBatch) {
								growthWriter.addStatement(statement.getSubject(), statement.getPredicate(),
										statement.getObject());
							}
							writesBuffered.countDown();
							growthWriter.commit();
							return namespace;
						}
					});
					assertTrue(writesBuffered.await(10, TimeUnit.SECONDS), "writer must buffer the growth batch");
					awaitGrowthPhase(store, LmdbSailStore.GrowthPhase.DRAIN_WRITERS);
					assertFalse(writer.isDone(),
							"growth must wait in DRAIN_WRITERS while the no-op update owner remains active");
					assertEquals(initialMapSize, mapSize(tripleStore),
							"TripleStore must not resize before the logical writer ends");
					assertSame(originalReadView, privateField(reader, "transactionReadView"),
							"the active update owner must keep its original snapshot until rollback");
					assertEquals(before.replayAccepted(),
							store.getBackingStore().growthMetricsSnapshot().replayAccepted(),
							"startUpdate must prevent replay before any mutation is buffered");
				}
				reader.rollback();
				assertNotNull(writer);
				String publishedNamespace = writer.get(15, TimeUnit.SECONDS);
				assertEquals(namespace, publishedNamespace);
				awaitTripleStoreGrowth(store, tripleStore, initialMapSize, publishedNamespace);
				assertEquals(before.replayAccepted(),
						store.getBackingStore().growthMetricsSnapshot().replayAccepted(),
						"the writer-protected attempt must complete without read replay");
				assertEquals(initialValueMapSize, mapSize(valueStoreOf(store)),
						"the update-owner barrier fixture must isolate TripleStore pressure");
				assertEquals(before.valueStoreResizes(),
						store.getBackingStore().growthMetricsSnapshot().valueStoreResizes(),
						"the update-owner barrier fixture must not resize ValueStore");
				try (SailConnection committed = store.getConnection()) {
					committed.begin(IsolationLevels.SNAPSHOT);
					assertTrue(committed.hasStatement(subject, predicate, VF.createLiteral("published"), false),
							"the writer's committed statement must be visible after the update owner rolls back");
					committed.rollback();
				}
			}
		} finally {
			store.shutDown();
		}
	}

	@ParameterizedTest
	@EnumSource(LmdbSailStore.MapResizeKind.class)
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void hardGrowthStillRejectsFrozenReplayWhileAWritingSnapshotIsHeld(LmdbSailStore.MapResizeKind kind,
			@TempDir File dataDir) throws Exception {
		long pressuredMap = (kind == LmdbSailStore.MapResizeKind.VALUE_STORE ? 8L : 4L) * 1024 * 1024;
		SoftPressureStore store = new SoftPressureStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(kind == LmdbSailStore.MapResizeKind.TRIPLE_STORE ? pressuredMap
						: TRIPLE_STORE_GROWTH_MAP_SIZE)
				.setValueDBSize(kind == LmdbSailStore.MapResizeKind.VALUE_STORE ? pressuredMap
						: TRIPLE_STORE_GROWTH_MAP_SIZE)
				.setBulkOperationSize(0)
				.setMapGrowthThreshold(TRIPLE_STORE_GROWTH_THRESHOLD)
				.setMapGrowthReadDrainTimeoutMillis(0)
				.setAutoGrow(true));
		IRI seedSubject = VF.createIRI("urn:hard-pressure:seed");
		IRI failedSubject = VF.createIRI("urn:hard-pressure:failed");
		Literal seedValue = VF.createLiteral("old");
		store.init();
		try {
			LmdbGcTestMaintenance.awaitPostReady(store);
			assertTrue(store.awaitIndexRebuild(10, TimeUnit.SECONDS));
			try (SailConnection seed = store.getConnection()) {
				seed.begin(IsolationLevels.SNAPSHOT);
				seed.addStatement(seedSubject, PREDICATE, seedValue);
				seed.commit();
			}
			LmdbSailStore backing = store.getBackingStore();
			TripleStore triples = backing.getTripleStore();
			ValueStore values = backing.valueStore();
			long beforeTripleMap = triples.mapSizeBytes();
			long beforeValueMap = values.mapSizeBytes();
			store.frozenStarts.set(0);
			try (SailConnection reader = store.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				reader.startUpdate(new UpdateContext(new InsertData("INSERT DATA {}"), null, null, false));
				try (CloseableIteration<? extends Statement> held = reader.getStatements(null, PREDICATE, null,
						false)) {
					Object originalView = privateField(reader, "transactionReadView");
					try (SailConnection writer = store.getConnection()) {
						writer.begin(IsolationLevels.SNAPSHOT);
						int rows = kind == LmdbSailStore.MapResizeKind.TRIPLE_STORE ? 100_000 : 5_000;
						String label = kind == LmdbSailStore.MapResizeKind.VALUE_STORE ? "v".repeat(2048) : "v";
						for (int i = 0; i < rows; i++) {
							writer.addStatement(VF.createIRI("urn:hard:" + i), PREDICATE, VF.createLiteral(label + i));
						}
						writer.addStatement(failedSubject, PREDICATE, VF.createLiteral("unacknowledged"));
						writer.setNamespace("failed", "urn:hard-pressure:unacknowledged:");
						SailException failure = assertThrows(SailException.class, writer::commit);
						assertTrue(failure.getCause() instanceof LmdbTransactionRetryException,
								"hard pressure must retain the writing-snapshot emergency refusal");
					}
					assertEquals(1, store.frozenStarts.get(), "hard refusal must not start another native attempt");
					assertNotNull(store.observedCapacity.get(), "the real allocation must reach native hard capacity");
					assertEquals(kind, store.observedCapacity.get().kind());
					assertEquals(beforeTripleMap, triples.mapSizeBytes());
					assertEquals(beforeValueMap, values.mapSizeBytes());
					assertSame(originalView, privateField(reader, "transactionReadView"));
					assertTrue(held.hasNext());
					assertEquals(VF.createStatement(seedSubject, PREDICATE, seedValue), held.next());
					assertFalse(held.hasNext(), "an aborted native prefix must stay outside the held writing snapshot");
					assertNull(reader.getNamespace("failed"));
				}
				reader.rollback();
			}
			try (SailConnection committed = store.getConnection()) {
				committed.begin(IsolationLevels.SNAPSHOT);
				assertTrue(committed.hasStatement(seedSubject, PREDICATE, seedValue, false));
				assertFalse(committed.hasStatement(failedSubject, PREDICATE, null, false));
				assertFalse(committed.hasStatement(VF.createIRI("urn:hard:0"), PREDICATE, null, false),
						"the native prefix must be completely rolled back");
				assertNull(committed.getNamespace("failed"));
				committed.rollback();
			}
		} finally {
			store.shutDown();
		}
	}

	@ParameterizedTest
	@EnumSource(LmdbSailStore.MapResizeKind.class)
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void softGrowthAllowsFrozenCommitBeforeTheWritingSnapshotRetires(LmdbSailStore.MapResizeKind kind,
			@TempDir File dataDir) throws Exception {
		// The persistent adjacency control occupies 3,891,200 bytes for this input. Five MiB retains the
		// unchanged 512 KiB hard reserve while crossing the 10% soft watermark; four MiB cannot do both.
		long pressuredMap = (kind == LmdbSailStore.MapResizeKind.VALUE_STORE ? 8L : 5L) * 1024 * 1024;
		SoftPressureStore store = new SoftPressureStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(kind == LmdbSailStore.MapResizeKind.TRIPLE_STORE ? pressuredMap
						: TRIPLE_STORE_GROWTH_MAP_SIZE)
				.setValueDBSize(kind == LmdbSailStore.MapResizeKind.VALUE_STORE ? pressuredMap
						: TRIPLE_STORE_GROWTH_MAP_SIZE)
				.setBulkOperationSize(0)
				.setMapGrowthThreshold(TRIPLE_STORE_GROWTH_THRESHOLD)
				.setMapGrowthReadDrainTimeoutMillis(0)
				.setAutoGrow(true));
		IRI oldSubject = VF.createIRI("urn:soft-pressure:old");
		IRI acknowledgedSubject = VF.createIRI("urn:soft-pressure:acknowledged");
		Literal oldValue = VF.createLiteral("old");
		Literal acknowledgedValue = VF.createLiteral("acknowledged");
		store.init();
		try {
			LmdbGcTestMaintenance.awaitPostReady(store);
			assertTrue(store.awaitIndexRebuild(10, TimeUnit.SECONDS));
			try (SailConnection seed = store.getConnection()) {
				seed.begin(IsolationLevels.SNAPSHOT);
				seed.addStatement(oldSubject, PREDICATE, oldValue);
				seed.commit();
			}
			LmdbSailStore backing = store.getBackingStore();
			TripleStore triples = backing.getTripleStore();
			ValueStore values = backing.valueStore();
			long beforeTripleMap = triples.mapSizeBytes();
			long beforeValueMap = values.mapSizeBytes();
			MapGrowthMetrics.Snapshot before = backing.growthMetricsSnapshot();
			store.frozenStarts.set(0);
			try (SailConnection reader = store.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				reader.startUpdate(new UpdateContext(new InsertData("INSERT DATA {}"), null, null, false));
				try (CloseableIteration<? extends Statement> held = reader.getStatements(null, PREDICATE, null,
						false)) {
					Object originalView = privateField(reader, "transactionReadView");
					assertNotNull(originalView);
					try (SailConnection writer = store.getConnection()) {
						writer.begin(IsolationLevels.SNAPSHOT);
						for (int i = 0; i < 10_000; i++) {
							writer.addStatement(VF.createIRI("urn:u:" + i), PREDICATE, VF.createLiteral("value"));
						}
						writer.addStatement(acknowledgedSubject, PREDICATE, acknowledgedValue);
						writer.setNamespace("acknowledged", "urn:soft-pressure:acknowledged:");
						// The other writing snapshot stays held until commit has actually acknowledged. A soft
						// watermark must not turn this admitted, physically fitting writer into an emergency resize.
						writer.commit();
					}
					assertEquals(1, store.frozenStarts.get(), "the acknowledged writer must use one frozen attempt");
					assertEquals(before.statementReplays(), backing.growthMetricsSnapshot().statementReplays(),
							"soft pressure must not abort the complete frozen input");
					assertEquals(LmdbSailStore.GrowthPhase.DRAIN_WRITERS,
							backing.growthMetricsSnapshot().currentPhase());
					assertEquals(beforeTripleMap, triples.mapSizeBytes(), "the held writer forbids TripleStore resize");
					assertEquals(beforeValueMap, values.mapSizeBytes(), "the held writer forbids ValueStore resize");
					long map = kind == LmdbSailStore.MapResizeKind.TRIPLE_STORE ? beforeTripleMap : beforeValueMap;
					long occupied = kind == LmdbSailStore.MapResizeKind.TRIPLE_STORE ? triples.occupiedBytes()
							: values.occupiedBytes();
					MapGrowthPolicy policy = new MapGrowthPolicy(TRIPLE_STORE_GROWTH_THRESHOLD);
					assertTrue(policy.requiresGrowth(map, occupied, 0L),
							"the committed footprint must cross soft pressure");
					assertFalse(policy.hardCapacityRequired(map, occupied, 0L),
							"the acknowledged input must leave the native hard-capacity reserve intact");
					assertSame(originalView, privateField(reader, "transactionReadView"));
					assertTrue(held.hasNext());
					assertEquals(VF.createStatement(oldSubject, PREDICATE, oldValue), held.next());
					assertFalse(held.hasNext(), "the original writing snapshot must exclude the acknowledged input");
					assertNull(reader.getNamespace("acknowledged"));
				}
				reader.rollback();
			}
			try (SailConnection committed = store.getConnection()) {
				committed.begin(IsolationLevels.SNAPSHOT);
				assertTrue(committed.hasStatement(oldSubject, PREDICATE, oldValue, false));
				assertTrue(committed.hasStatement(acknowledgedSubject, PREDICATE, acknowledgedValue, false));
				assertEquals("urn:soft-pressure:acknowledged:", committed.getNamespace("acknowledged"));
				int count = 0;
				try (CloseableIteration<? extends Statement> all = committed.getStatements(null, PREDICATE, null,
						false)) {
					while (all.hasNext()) {
						all.next();
						count++;
					}
				}
				assertEquals(10_002, count);
				committed.rollback();
			}
			assertTrue(kind == LmdbSailStore.MapResizeKind.TRIPLE_STORE ? triples.mapSizeBytes() > beforeTripleMap
					: values.mapSizeBytes() > beforeValueMap,
					"managed growth must finish after the final writing snapshot retires");
			assertEquals(before.replayAccepted(), backing.growthMetricsSnapshot().replayAccepted(),
					"writing snapshots must retain their original epoch without relational replay");
		} finally {
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void readReplayLeaseRejectsNoneAndAcceptsCompatibleRequests(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(TRIPLE_STORE_GROWTH_MAP_SIZE)
				.setMapGrowthThreshold(TRIPLE_STORE_GROWTH_THRESHOLD)
				.setMapGrowthReadDrainTimeoutMillis(0)
				.setAutoGrow(true));
		store.init();
		try {
			TripleStore tripleStore = tripleStoreOf(store);
			long initialMapSize = mapSize(tripleStore);
			IRI subject = VF.createIRI("urn:snapshot-lifetime:none:seed");
			IRI growthPredicate = VF.createIRI("urn:snapshot-lifetime:none:growth-predicate");
			try (SailConnection seed = store.getConnection()) {
				seed.begin(IsolationLevels.SNAPSHOT);
				seed.addStatement(subject, PREDICATE, VF.createLiteral("first"));
				seed.addStatement(subject, PREDICATE, VF.createLiteral("second"));
				seed.commit();
			}
			MapGrowthMetrics.Snapshot before = store.getBackingStore().growthMetricsSnapshot();
			SailSource source = store.getBackingStore().getExplicitSailSource();
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				assertNotNull(privateField(connection, "readAttemptLease"),
						"NONE isolation must still register native-view ownership");
				try (CloseableIteration<? extends Statement> results = connection.getStatements(subject, PREDICATE,
						null,
						false)) {
					assertFalse(snapshotReadViewLeases((LmdbStoreConnection) connection).isEmpty(),
							"an open NONE result must own its native read view");
					String namespace;
					try (SailSink writer = source.sink(IsolationLevels.NONE)) {
						namespace = addTripleStoreGrowthDemand(writer, initialMapSize);
						for (int i = 0; i < 10_000; i++) {
							writer.approve(VF.createIRI("urn:snapshot-lifetime:none:growth:" + i), growthPredicate,
									VF.createLiteral("growth"), null);
						}
						writer.flush();
					}
					try (SailDataset barrier = source.dataset(IsolationLevels.SNAPSHOT_READ)) {
						assertEquals(namespace, barrier.getNamespace("growth-demand"),
								"the independent raw dataset must observe the complete namespace publication");
					}
					assertTrue(mapSize(tripleStore) > initialMapSize,
							"the raw source publication must finish TripleStore map growth");
				}
				MapGrowthMetrics.Snapshot after = store.getBackingStore().growthMetricsSnapshot();
				assertTrue(after.replayRequests() > before.replayRequests(),
						"map growth must notify the registered NONE read attempt");
				assertEquals(before.replayAccepted(), after.replayAccepted(),
						"NONE must remain ineligible for transparent read replay");
				connection.rollback();
			}
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.READ_UNCOMMITTED);
				assertTrue(privateField(connection, "readAttemptLease") != null,
						"a weaker request upgraded to a compatible supported level must register for replay");
				connection.rollback();
			}
			for (IsolationLevels level : List.of(IsolationLevels.READ_COMMITTED, IsolationLevels.SNAPSHOT_READ,
					IsolationLevels.SNAPSHOT, IsolationLevels.SERIALIZABLE)) {
				try (SailConnection connection = store.getConnection()) {
					connection.begin(level);
					assertTrue(privateField(connection, "readAttemptLease") != null,
							"supported isolation level " + level + " must register for transparent replay");
					connection.rollback();
				}
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	// Expired observed reads are canceled; untouched siblings can still replay.
	void readCommittedObservedResultIsCancelledAfterGraceWhileSiblingReplays(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(TRIPLE_STORE_GROWTH_MAP_SIZE)
				.setValueDBSize(128L * 1024L * 1024L)
				.setMapGrowthThreshold(TRIPLE_STORE_GROWTH_THRESHOLD)
				.setMapGrowthReadDrainTimeoutMillis(3_000)
				.setAutoGrow(true));
		IRI observedPredicate = VF.createIRI("urn:snapshot-lifetime:mixed-observation:observed-predicate");
		IRI replayPredicate = VF.createIRI("urn:snapshot-lifetime:mixed-observation:replay-predicate");
		IRI firstObserved = VF.createIRI("urn:snapshot-lifetime:mixed-observation:first");
		IRI secondObserved = VF.createIRI("urn:snapshot-lifetime:mixed-observation:second");
		IRI replayedSubject = VF.createIRI("urn:snapshot-lifetime:mixed-observation:published");
		long initialMapSize;

		store.init();
		try {
			try (SailConnection seed = store.getConnection()) {
				seed.begin(IsolationLevels.SNAPSHOT);
				seed.addStatement(firstObserved, observedPredicate, VF.createLiteral("first"));
				seed.addStatement(secondObserved, observedPredicate, VF.createLiteral("second"));
				seed.commit();
			}
			TripleStore tripleStore = tripleStoreOf(store);
			initialMapSize = mapSize(tripleStore);
			try (SailConnection reader = store.getConnection();
					ExecutorService writers = Executors.newSingleThreadExecutor()) {
				reader.begin(IsolationLevels.READ_COMMITTED);
				try (CloseableIteration<? extends Statement> observed = reader.getStatements(null, observedPredicate,
						null,
						false);
						CloseableIteration<? extends Statement> unobserved = reader.getStatements(replayedSubject,
								replayPredicate, null, false)) {
					List<Object> oldViews = snapshotReadViewLeases((LmdbStoreConnection) reader);
					assertTrue(oldViews.size() >= 2, "each open RC result must pin its own read view");
					assertTrue(observed.hasNext());
					assertEquals("first", observed.next().getObject().stringValue());
					Set<?> registeredResults = (Set<?>) privateField(reader, "replayableIterations");
					Object observedResult = registeredResults.stream()
							.filter(result -> isObserved(result, true))
							.findFirst()
							.orElseThrow();
					Object unobservedResult = registeredResults.stream()
							.filter(result -> isObserved(result, false))
							.findFirst()
							.orElseThrow();
					// Observed iterations keep these in readViews; only replay-eligible iterations fill growthViews.
					Set<Object> observedGrowthViews = snapshotIterationReadViews(reader, observedResult);
					assertFalse(observedGrowthViews.isEmpty(),
							"the observed result must pin its original native views");

					MapGrowthMetrics.Snapshot beforeGrowth = store.getBackingStore().growthMetricsSnapshot();
					CountDownLatch writesBuffered = new CountDownLatch(1);
					Future<String> writer = writers.submit(() -> {
						try (SailConnection connection = store.getConnection()) {
							connection.begin(IsolationLevels.SNAPSHOT);
							String namespace = addTripleStoreHardGrowthDemand(connection, tripleStore);
							for (int i = 0; i < 25_000; i++) {
								connection.addStatement(
										VF.createIRI("urn:snapshot-lifetime:mixed-observation:growth:" + i),
										replayPredicate, VF.createLiteral("growth"));
							}
							connection.addStatement(replayedSubject, replayPredicate, VF.createLiteral("published"));
							writesBuffered.countDown();
							connection.commit();
							return namespace;
						} catch (SailException failure) {
							throw new RuntimeException(failure);
						}
					});
					assertTrue(writesBuffered.await(10, TimeUnit.SECONDS), "writer must buffer the growth batch");
					Set<Object> unobservedGrowthViews = awaitResultGrowthViews(reader, unobservedResult);
					awaitForcedReadViewInvalidation(store, writer, beforeGrowth);

					SailException observedFailure = assertThrows(SailException.class,
							observed::hasNext,
							"an observed result whose read grace expired must be cancelled before remapping");
					LmdbSailStore.MapResizeConflictException observedConflict = findCause(observedFailure,
							LmdbSailStore.MapResizeConflictException.class);
					assertNotNull(observedConflict,
							"the observed-result cancellation must preserve its typed resize cause");
					assertEquals(LmdbSailStore.MapResizeKind.TRIPLE_STORE, observedConflict.kind());
					observed.close();
					String namespace = writer.get(15, TimeUnit.SECONDS);
					awaitTripleStoreGrowth(store, tripleStore, initialMapSize, namespace);
					assertTrue(mapSize(tripleStore) > initialMapSize,
							"the writer must grow the map while the sibling result remains unobserved");
					assertEquals(beforeGrowth.valueStoreResizes(),
							store.getBackingStore().growthMetricsSnapshot().valueStoreResizes(),
							"the complete input must fit the other environment without dictionary growth");
					for (Object oldView : oldViews) {
						assertTrue((boolean) privateField(oldView, "closed"),
								"all original RC result views must close before the replacement generation is published");
					}
					for (Object oldView : observedGrowthViews) {
						assertTrue((boolean) privateField(oldView, "closed"),
								"canceling the observed result must release its old native views");
						assertEquals(LmdbSailStore.MapResizeKind.TRIPLE_STORE,
								privateField(oldView, "invalidatedKind"),
								"the observed result must be the view invalidated after grace");
					}
					for (Object oldView : unobservedGrowthViews) {
						assertTrue((boolean) privateField(oldView, "closed"),
								"replaying the unobserved result must release its old native views");
						assertNull(privateField(oldView, "invalidatedKind"),
								"the unobserved result must release its old view before resize, without forced invalidation");
					}
					Set<?> remainingResults = (Set<?>) privateField(reader, "replayableIterations");
					assertEquals(1, remainingResults.size(),
							"the closed observed result must no longer be registered");
					Object remainingResult = remainingResults.iterator().next();
					assertFalse((boolean) privateField(remainingResult, "observed"),
							"the unconsumed result must remain unobserved until outward exposure");

					assertTrue(unobserved.hasNext(),
							"a different unobserved RC result must replay despite an observed sibling result");
					assertEquals("published", unobserved.next().getObject().stringValue());
					assertFalse(unobserved.hasNext());
				}
				reader.rollback();
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 20, unit = TimeUnit.SECONDS)
	void readCommittedObservedResultCanFinishWithinGrowthGrace(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(TRIPLE_STORE_GROWTH_MAP_SIZE)
				.setValueDBSize(128L * 1024L * 1024L)
				.setMapGrowthThreshold(TRIPLE_STORE_GROWTH_THRESHOLD)
				.setMapGrowthReadDrainTimeoutMillis(30_000)
				.setAutoGrow(true));
		IRI observedPredicate = VF.createIRI("urn:snapshot-lifetime:grace:observed-predicate");
		IRI firstObserved = VF.createIRI("urn:snapshot-lifetime:grace:first");
		IRI secondObserved = VF.createIRI("urn:snapshot-lifetime:grace:second");
		IRI publishedSubject = VF.createIRI("urn:snapshot-lifetime:grace:published");
		IRI growthPredicate = VF.createIRI("urn:snapshot-lifetime:grace:growth-predicate");

		store.init();
		try {
			try (SailConnection seed = store.getConnection()) {
				seed.begin(IsolationLevels.SNAPSHOT);
				seed.addStatement(firstObserved, observedPredicate, VF.createLiteral("first"));
				seed.addStatement(secondObserved, observedPredicate, VF.createLiteral("second"));
				seed.commit();
			}
			TripleStore tripleStore = tripleStoreOf(store);
			long initialMapSize = mapSize(tripleStore);
			MapGrowthMetrics.Snapshot beforeGrowth = store.getBackingStore().growthMetricsSnapshot();
			try (SailConnection reader = store.getConnection();
					ExecutorService writers = Executors.newSingleThreadExecutor()) {
				reader.begin(IsolationLevels.READ_COMMITTED);
				try (CloseableIteration<? extends Statement> observed = reader.getStatements(null, observedPredicate,
						null, false)) {
					List<Object> oldViews = snapshotReadViewLeases((LmdbStoreConnection) reader);
					assertTrue(observed.hasNext());
					assertEquals("first", observed.next().getObject().stringValue());
					CountDownLatch writesBuffered = new CountDownLatch(1);
					Future<String> writer = writers.submit(() -> {
						try (SailConnection connection = store.getConnection()) {
							connection.begin(IsolationLevels.SNAPSHOT);
							String namespace = addTripleStoreHardGrowthDemand(connection, tripleStore);
							for (int i = 0; i < 25_000; i++) {
								connection.addStatement(
										VF.createIRI("urn:snapshot-lifetime:grace:growth:" + i), growthPredicate,
										VF.createLiteral("growth"));
							}
							connection.addStatement(publishedSubject, growthPredicate, VF.createLiteral("published"));
							writesBuffered.countDown();
							connection.commit();
							return namespace;
						} catch (SailException failure) {
							throw new RuntimeException(failure);
						}
					});
					assertTrue(writesBuffered.await(10, TimeUnit.SECONDS), "writer must buffer the growth batch");
					long drainWaitDeadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
					MapGrowthMetrics.Snapshot duringDrain = store.getBackingStore().growthMetricsSnapshot();
					while (duringDrain.readerDrainWaitCount() <= beforeGrowth.readerDrainWaitCount()) {
						assertFalse(writer.isDone(),
								"the writer must remain parked while its observed result is retained");
						if (System.nanoTime() >= drainWaitDeadline) {
							throw new AssertionError(
									"the writer did not enter reader-drain wait; metrics=" + duringDrain);
						}
						Thread.yield();
						duringDrain = store.getBackingStore().growthMetricsSnapshot();
					}
					assertTrue(store.getBackingStore().growthAdmissionClosed(),
							"the observed reader must hold a closed growth admission while the writer drains");
					assertFalse(writer.isDone(),
							"the writer must remain pending until the observed result is released");
					assertEquals(initialMapSize, mapSize(tripleStore),
							"the TripleStore map must remain unchanged while reader grace is waiting");
					assertTrue(
							store.getBackingStore().growthMetricsSnapshot().growthEpisodes() > beforeGrowth
									.growthEpisodes(),
							"the result must finish during the newly admitted writer's growth episode");

					assertTrue(observed.hasNext(), "the observed result must remain readable during its grace period");
					assertEquals("second", observed.next().getObject().stringValue());
					assertFalse(observed.hasNext(), "the result must finish naturally while the writer is parked");
					observed.close();
					reader.rollback();
					String namespace = writer.get(10, TimeUnit.SECONDS);
					awaitTripleStoreGrowth(store, tripleStore, initialMapSize, namespace);
					assertEquals(beforeGrowth.valueStoreResizes(),
							store.getBackingStore().growthMetricsSnapshot().valueStoreResizes(),
							"the complete input must fit the other environment without dictionary growth");
					try (SailConnection committed = store.getConnection()) {
						committed.begin(IsolationLevels.SNAPSHOT);
						assertEquals(namespace, committed.getNamespace("growth-demand"));
						assertTrue(committed.hasStatement(publishedSubject, growthPredicate,
								VF.createLiteral("published"), false),
								"the complete buffered publication must survive the reader drain");
						committed.rollback();
					}

					assertTrue(mapSize(tripleStore) > initialMapSize,
							"the admitted writer must complete the TripleStore resize");
					for (Object oldView : oldViews) {
						assertTrue((boolean) privateField(oldView, "closed"),
								"natural result completion must release its original native read views");
						assertNull(privateField(oldView, "invalidatedKind"),
								"a result completed within grace must not be forcibly invalidated");
					}
					MapGrowthMetrics.Snapshot afterGrowth = store.getBackingStore().growthMetricsSnapshot();
					assertEquals(beforeGrowth.forcedInvalidatedViews(), afterGrowth.forcedInvalidatedViews(),
							"a reader that naturally finishes during grace must not be counted as forced invalidation");
					assertEquals(beforeGrowth.replayAccepted(), afterGrowth.replayAccepted(),
							"an observed result must finish in place rather than replay");
				}
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void writerSnapshotIsRetiredAfterPrepare(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc").setForceSync(true));
		IRI subject = VF.createIRI("urn:snapshot-lifetime:prepared-writer:subject");
		IRI predicate = VF.createIRI("urn:snapshot-lifetime:prepared-writer:predicate");

		store.init();
		try {
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(subject, predicate, VF.createLiteral("staged"));
				try (CloseableIteration<? extends Statement> statements = writer.getStatements(subject, predicate, null,
						false)) {
					assertTrue(statements.hasNext());
				}

				Object writerReadView = privateField(writer, "transactionReadView");
				assertTrue(writerReadView != null, "the writer must retain its snapshot through validation");
				Object writerReadViewLease = privateField(writerReadView, "growthLease");
				assertFalse((boolean) privateField(writerReadViewLease, "closed"));

				writer.prepare();

				assertTrue((boolean) privateField(writerReadViewLease, "closed"),
						"prepare must retire the writer-owned native snapshot before branch locks are retained");
				assertNull(privateField(writer, "transactionReadView"),
						"the connection must not retain a prepared transaction's native snapshot");
				writer.commit();
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void openWriterResultRemainsUsableAfterPrepareAndCommit(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc").setForceSync(true));
		IRI subject = VF.createIRI("urn:snapshot-lifetime:open-writer-result:subject");
		IRI predicate = VF.createIRI("urn:snapshot-lifetime:open-writer-result:predicate");

		store.init();
		try {
			try (SailConnection seed = store.getConnection()) {
				seed.begin(IsolationLevels.SNAPSHOT);
				seed.addStatement(subject, predicate, VF.createLiteral("visible"));
				seed.commit();
			}

			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				try (CloseableIteration<? extends Statement> statements = writer.getStatements(subject, predicate, null,
						false)) {
					assertTrue(statements.hasNext());
					Object writerReadView = privateField(writer, "transactionReadView");
					writer.addStatement(subject, predicate, VF.createLiteral("staged"));
					writer.prepare();
					Object writerReadViewLease = privateField(writerReadView, "growthLease");
					assertFalse((boolean) privateField(writerReadViewLease, "closed"),
							"an open result cursor must retain its native snapshot through prepare");
					writer.commit();
					assertFalse((boolean) privateField(writerReadViewLease, "closed"),
							"commit must not close a native snapshot still borrowed by a result cursor");

					Statement escaped = statements.next();
					assertFalse(statements.hasNext());
					assertEquals("visible", escaped.getObject().stringValue(),
							"values returned before cursor close must remain usable after native retirement");
					assertTrue((boolean) privateField(writerReadViewLease, "closed"),
							"the native snapshot should retire after its last borrower closes");
				}
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void finishedWriterResultRemainsBoundToItsAttemptAfterNextBegin(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc").setForceSync(true));
		IRI subject = VF.createIRI("urn:snapshot-lifetime:finished-result:subject");
		IRI predicate = VF.createIRI("urn:snapshot-lifetime:finished-result:predicate");

		store.init();
		try {
			try (SailConnection seed = store.getConnection()) {
				seed.begin(IsolationLevels.SNAPSHOT);
				seed.addStatement(subject, predicate, VF.createLiteral("visible"));
				seed.commit();
			}

			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				try (CloseableIteration<? extends Statement> statements = writer.getStatements(subject, predicate, null,
						false)) {
					Object oldReadView = privateField(writer, "transactionReadView");
					assertTrue(oldReadView != null, "opening a result must capture its original transaction view");
					Object oldReadViewLease = privateField(oldReadView, "growthLease");
					writer.addStatement(subject, predicate, VF.createLiteral("staged"));
					writer.prepare();
					writer.commit();

					writer.begin(IsolationLevels.SNAPSHOT);
					assertFalse((boolean) privateField(writer, "transactionObserved"),
							"a new transaction must begin with no outward observations");
					assertFalse((boolean) privateField(oldReadViewLease, "closed"),
							"the old result must retain its original native view after the next begin");

					assertTrue(statements.hasNext());
					assertFalse((boolean) privateField(writer, "transactionObserved"),
							"exposing an old result must not observe the new transaction");
					assertFalse((boolean) privateField(oldReadViewLease, "closed"),
							"the old result must not be replaced with a view from the new transaction");
					List<Statement> escapedStatements = new ArrayList<>();
					escapedStatements.add(statements.next());
					while (statements.hasNext()) {
						escapedStatements.add(statements.next());
					}
					assertTrue(escapedStatements.stream()
							.anyMatch(
									statement -> "visible".equals(statement.getObject().stringValue())));
					assertTrue((boolean) privateField(oldReadViewLease, "closed"),
							"closing the old result must release its original native view");
					writer.rollback();
				}
			}
		} finally {
			store.shutDown();
		}
	}

